function detectObsidianLang() {
  try {
    if (typeof obsidian.getLanguage === "function") {
      const appLang = obsidian.getLanguage();
      if (appLang) return String(appLang).toLowerCase().startsWith("zh") ? "zh" : "en";
    }
    const stored = typeof window !== "undefined" ? window.localStorage?.getItem("language") : "";
    if (stored) return String(stored).toLowerCase().startsWith("zh") ? "zh" : "en";
    const nav = typeof navigator !== "undefined" ? navigator.language : "";
    if (nav) return String(nav).toLowerCase().startsWith("zh") ? "zh" : "en";
  } catch {
    // Fall back to Chinese if environment inspection fails.
  }
  return "zh";
}

function resolveLang(settings) {
  const pref = settings?.language || "auto";
  if (pref === "en") return "en";
  if (pref === "zh") return "zh";
  return detectObsidianLang();
}

function translate(lang, key, vars = {}) {
  const table = I18N[lang] || I18N.zh;
  const template = table[key] ?? I18N.zh[key] ?? key;
  return String(template).replace(/\{(\w+)\}/g, (_, name) => (
    vars[name] !== undefined && vars[name] !== null ? String(vars[name]) : ""
  ));
}

function asString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function parseFrontmatter(raw) {
  const match = raw.match(/^---\s*\r?\n([\s\S]*?)\r?\n---\s*(?:\r?\n|$)/);
  if (!match) return { data: {}, body: raw };

  const data = {};
  const lines = match[1].split(/\r?\n/);
  let activeListKey = null;
  for (const line of lines) {
    const listItem = line.match(/^\s*-\s*(.+?)\s*$/);
    if (listItem && activeListKey) {
      if (!Array.isArray(data[activeListKey])) data[activeListKey] = [];
      data[activeListKey].push(stripYamlScalar(listItem[1]));
      continue;
    }

    const pair = line.match(/^\s*([\w-]+)\s*:\s*(.*?)\s*$/);
    if (!pair) continue;
    const key = pair[1];
    const value = pair[2];
    if (!value) {
      data[key] = [];
      activeListKey = key;
      continue;
    }
    activeListKey = null;
    if (value.startsWith("[") && value.endsWith("]")) {
      data[key] = value
        .slice(1, -1)
        .split(",")
        .map((item) => stripYamlScalar(item))
        .filter(Boolean);
    } else {
      data[key] = stripYamlScalar(value);
    }
  }

  return { data, body: raw.slice(match[0].length) };
}

function stripYamlScalar(value) {
  const text = asString(value);
  if ((text.startsWith("\"") && text.endsWith("\"")) ||
      (text.startsWith("'") && text.endsWith("'"))) {
    return text.slice(1, -1);
  }
  return text;
}

function normalizeList(value) {
  if (Array.isArray(value)) return value.map(asString).filter(Boolean);
  if (!value) return [];
  return String(value)
    .split(/[，,\s]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function firstHeading(body) {
  const match = body.match(/^\s*#\s+(.+?)\s*$/m);
  return match ? match[1].trim() : "";
}

function removeDuplicateTitle(body, title) {
  const lines = body.split(/\r?\n/);
  const firstContentIndex = lines.findIndex((line) => line.trim() !== "");
  if (firstContentIndex < 0) return body.trim();
  const first = lines[firstContentIndex].match(/^\s*#\s+(.+?)\s*$/);
  if (first && first[1].trim() === title.trim()) {
    lines.splice(firstContentIndex, 1);
  }
  return lines.join("\n").trim();
}

function findLocalImages(body) {
  const paths = [];
  const wikiPattern = /!\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|[^\]]+)?\]\]/g;
  const markdownPattern = /!\[[^\]]*\]\(([^)]+)\)/g;
  for (const match of body.matchAll(wikiPattern)) paths.push(match[1].trim());
  for (const match of body.matchAll(markdownPattern)) {
    const target = match[1].trim().replace(/^<|>$/g, "");
    if (!/^(https?:|data:|file:)/i.test(target)) paths.push(target);
  }
  return [...new Set(paths)];
}

function yamlString(value) {
  return JSON.stringify(asString(value));
}

function preprocessObsidianMarkdown(body) {
  const lines = body.split(/\r?\n/);
  const output = [];
  let inFence = false;
  let fenceChar = "";

  for (const rawLine of lines) {
    const fenceMatch = rawLine.match(/^\s*(`{3,}|~{3,})/);
    if (fenceMatch) {
      const marker = fenceMatch[1][0];
      if (!inFence) {
        inFence = true;
        fenceChar = marker;
      } else if (marker === fenceChar) {
        inFence = false;
        fenceChar = "";
      }
      output.push(rawLine);
      continue;
    }

    if (inFence) {
      output.push(rawLine);
      continue;
    }

    let line = rawLine;
    // Strip inline Obsidian comments: %%...%%
    line = line.replace(/%%[\s\S]*?%%/g, "");
    // Convert Obsidian Callout header: > [!note] Title -> > **Title**
    line = line.replace(
      /^(\s*>\s*)\[!([A-Za-z0-9_-]+)\][+-]?\s*(.*)$/,
      (_, prefix, type, title) => {
        const label = (title || "").trim() || type.toUpperCase();
        return `${prefix}**${label}**`;
      }
    );
    // Convert [[Target|Alias]] -> Alias and [[Target]] -> Target (keep ![[embed]] intact)
    line = line.replace(/(?<!!)\[\[([^\]|#]+)(?:#[^\]|]+)?(?:\|([^\]]+))?\]\]/g, (_, target, alias) => {
      return (alias || target || "").trim();
    });
    output.push(line);
  }

  return output.join("\n").trim();
}

function safeDraftFileName(title, articleId, fallbackTitle = "未命名草稿") {
  const cleaned = asString(title)
    .replace(/[<>:"/\\|?*\u0000-\u001f]/g, "-")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[. ]+$/g, "")
    .slice(0, 80);
  return `${cleaned || fallbackTitle}-${articleId}.md`;
}

class TextInputModal extends Modal {
  constructor(app, { title, placeholder = "", initialValue = "", submitText = "OK", cancelText = "Cancel" }) {
    super(app);
    this.titleText = title;
    this.placeholder = placeholder;
    this.initialValue = initialValue;
    this.submitText = submitText;
    this.cancelText = cancelText;
    this.resolved = false;
    this.resolver = null;
  }

  openAndWait() {
    return new Promise((resolve) => {
      this.resolver = resolve;
      this.open();
    });
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h3", { text: this.titleText });
    const input = contentEl.createEl("input", {
      type: "text",
      placeholder: this.placeholder,
      value: this.initialValue,
      cls: "csdn-modal-input",
    });
    const finish = (value) => {
      if (this.resolved) return;
      this.resolved = true;
      this.close();
      this.resolver?.(value);
    };
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        finish(input.value.trim());
      }
    });
    const actions = contentEl.createDiv({ cls: "csdn-modal-actions" });
    const cancelBtn = actions.createEl("button", { text: this.cancelText });
    cancelBtn.addEventListener("click", () => finish(null));
    const okBtn = actions.createEl("button", { text: this.submitText, cls: "mod-cta" });
    okBtn.addEventListener("click", () => finish(input.value.trim()));
    window.setTimeout(() => {
      input.focus();
      input.select();
    }, 10);
  }

  onClose() {
    this.contentEl.empty();
    if (!this.resolved) {
      this.resolved = true;
      this.resolver?.(null);
    }
  }
}

class ConfirmModal extends Modal {
  constructor(app, { title, message, confirmText = "OK", cancelText = "Cancel", isWarning = true }) {
    super(app);
    this.titleText = title;
    this.message = message;
    this.confirmText = confirmText;
    this.cancelText = cancelText;
    this.isWarning = isWarning;
    this.resolved = false;
    this.resolver = null;
  }

  openAndWait() {
    return new Promise((resolve) => {
      this.resolver = resolve;
      this.open();
    });
  }

  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.createEl("h3", { text: this.titleText });
    contentEl.createEl("p", { text: this.message });
    const finish = (confirmed) => {
      if (this.resolved) return;
      this.resolved = true;
      this.close();
      this.resolver?.(confirmed);
    };
    const actions = contentEl.createDiv({ cls: "csdn-modal-actions" });
    const cancelBtn = actions.createEl("button", { text: this.cancelText });
    cancelBtn.addEventListener("click", () => finish(false));
    const okBtn = actions.createEl("button", {
      text: this.confirmText,
      cls: this.isWarning ? "mod-warning" : "mod-cta",
    });
    okBtn.addEventListener("click", () => finish(true));
  }

  onClose() {
    this.contentEl.empty();
    if (!this.resolved) {
      this.resolved = true;
      this.resolver?.(false);
    }
  }
}

class QrLoginModal extends Modal {
  constructor(app, plugin, account) {
    super(app);
    this.plugin = plugin;
    this.account = account;
    this.mode = "wechat";
    this.pollTimer = null;
    this.closed = false;
    this.loggedIn = false;
    this.polling = false;
  }

  onOpen() {
    const { contentEl } = this;
    const t = (k, v) => this.plugin.t(k, v);
    const displayName = this.plugin.accountDisplayName(this.account);
    contentEl.empty();
    contentEl.addClass("csdn-qr-modal");

    contentEl.createEl("h3", { text: t("qrModalTitle", { name: displayName }) });
    contentEl.createEl("p", {
      text: t("qrModalSub"),
      cls: "csdn-qr-modal-sub",
    });

    const tabs = contentEl.createDiv({ cls: "csdn-qr-tabs" });
    this.wechatBtn = tabs.createEl("button", { text: t("qrTabWechat") });
    this.appBtn = tabs.createEl("button", { text: t("qrTabApp") });
    this.wechatBtn.addEventListener("click", () => void this.switchMode("wechat"));
    this.appBtn.addEventListener("click", () => void this.switchMode("app"));

    this.frameEl = contentEl.createDiv({ cls: "csdn-qr-frame" });
    this.statusEl = contentEl.createEl("p", {
      text: t("qrConnecting"),
      cls: "csdn-qr-status",
    });

    const actions = contentEl.createDiv({ cls: "csdn-qr-actions" });
    this.refreshBtn = actions.createEl("button", { text: t("qrRefreshBtn") });
    this.refreshBtn.addEventListener("click", () => void this.refreshQr());

    const browserBtn = actions.createEl("button", { text: t("qrUseBrowserBtn") });
    browserBtn.addEventListener("click", async () => {
      this.close();
      try {
        await this.plugin.loginAccount(this.account.id);
        new Notice(t("openedBrowserLoginNotice", { name: displayName }), 8000);
      } catch (error) {
        new Notice(t("openBrowserLoginError", { error: error.message }), 10000);
      }
    });

    const cancelBtn = actions.createEl("button", { text: t("cancel") });
    cancelBtn.addEventListener("click", () => this.close());

    this.updateModeButtons();
    this.renderFrame({ status: "loading", qr_data_url: "", message: t("qrFetching") });
    void this.startSession();
  }

  updateModeButtons() {
    this.wechatBtn?.toggleClass("is-active", this.mode === "wechat");
    this.appBtn?.toggleClass("is-active", this.mode === "app");
  }

  renderFrame(state) {
    if (this.closed || !this.frameEl || !this.statusEl) return;
    const t = (k, v) => this.plugin.t(k, v);
    const status = state?.status || "loading";
    const qrDataUrl = state?.qr_data_url || "";
    const message = state?.message || t("qrFetching");

    this.frameEl.empty();
    if (qrDataUrl) {
      const img = this.frameEl.createEl("img");
      img.src = qrDataUrl;
      img.alt = t("qrImgAlt");
    } else if (status !== "error" && status !== "expired" && status !== "already_logged_in") {
      this.frameEl.createDiv({ cls: "csdn-qr-placeholder" });
    }

    if (status === "already_logged_in") {
      const overlay = this.frameEl.createDiv({ cls: "csdn-qr-overlay" });
      overlay.createSpan({ text: t("qrAlreadyLoggedIn") });
      const reloginBtn = overlay.createEl("button", { text: t("qrRescanBtn"), cls: "mod-cta" });
      reloginBtn.addEventListener("click", () => void this.startSession(true));
    } else if (status === "expired" || status === "error") {
      const overlay = this.frameEl.createDiv({ cls: "csdn-qr-overlay" });
      overlay.createSpan({ text: status === "expired" ? t("qrExpiredTitle") : t("qrErrorTitle") });
      const retry = overlay.createEl("button", { text: t("retry"), cls: "mod-cta" });
      retry.addEventListener("click", () => void this.refreshQr());
    } else if (status === "scanned") {
      const overlay = this.frameEl.createDiv({ cls: "csdn-qr-overlay" });
      overlay.createSpan({ text: t("qrScannedTitle") });
      overlay.createSpan({ text: t("qrScannedSub") });
    } else if (status === "logged_in") {
      const overlay = this.frameEl.createDiv({ cls: "csdn-qr-overlay" });
      overlay.createSpan({ text: t("qrSuccessTitle") });
    }

    this.statusEl.setText(message);
    this.statusEl.removeClass("is-success", "is-error");
    if (status === "logged_in" || status === "scanned" || status === "already_logged_in") {
      this.statusEl.addClass("is-success");
    } else if (status === "error" || status === "expired") {
      this.statusEl.addClass("is-error");
    }
  }

  async startSession(forceRelogin = false) {
    this.clearPoll();
    this.renderFrame({
      status: "loading",
      qr_data_url: "",
      message: forceRelogin ? this.plugin.t("qrClearingOld") : this.plugin.t("qrFetching"),
    });
    try {
      const state = await this.plugin.startQrLogin(this.account.id, this.mode, forceRelogin);
      if (this.closed) return;
      this.renderFrame(state);
      this.schedulePoll();
    } catch (error) {
      if (this.closed) return;
      this.renderFrame({ status: "error", qr_data_url: "", message: error.message });
    }
  }

  async switchMode(nextMode) {
    if (this.mode === nextMode) return;
    this.mode = nextMode;
    this.updateModeButtons();
    await this.refreshQr();
  }

  async refreshQr() {
    if (this.closed) return;
    this.clearPoll();
    this.renderFrame({ status: "loading", qr_data_url: "", message: this.plugin.t("qrRefreshing") });
    try {
      const state = await this.plugin.refreshQrLogin(this.account.id, this.mode);
      if (this.closed) return;
      this.renderFrame(state);
      this.schedulePoll();
    } catch (error) {
      if (this.closed) return;
      this.renderFrame({ status: "error", qr_data_url: "", message: error.message });
    }
  }

  clearPoll() {
    if (this.pollTimer !== null) {
      window.clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }
  }

  schedulePoll() {
    this.clearPoll();
    if (this.closed || this.loggedIn) return;
    this.pollTimer = window.setTimeout(() => void this.pollOnce(), 1200);
  }

  async pollOnce() {
    if (this.closed || this.loggedIn || this.polling) return;
    this.polling = true;
    try {
      const state = await this.plugin.getQrLoginStatus(this.account.id);
      if (this.closed) return;
      if (state.mode && state.mode !== this.mode) {
        this.mode = state.mode;
        this.updateModeButtons();
      }
      this.renderFrame(state);

      if (state.status === "logged_in") {
        this.loggedIn = true;
        this.clearPoll();
        if (this.plugin.settings.activeAccountId !== this.account.id) {
          this.plugin.settings.activeAccountId = this.account.id;
          await this.plugin.saveSettings();
        }
        new Notice(this.plugin.t("qrSuccessNotice", {
          name: this.plugin.accountDisplayName(this.account),
        }), 6000);
        this.plugin.refreshOpenDraftViews();
        window.setTimeout(() => {
          if (!this.closed) this.close();
        }, 700);
        return;
      }
      if (
        state.status === "error"
        || state.status === "expired"
        || state.status === "cancelled"
        || state.status === "already_logged_in"
      ) {
        this.clearPoll();
        return;
      }
      this.schedulePoll();
    } catch (error) {
      if (this.closed) return;
      this.renderFrame({
        status: "error",
        qr_data_url: "",
        message: this.plugin.t("qrPollError", { error: error.message }),
      });
      this.clearPoll();
    } finally {
      this.polling = false;
    }
  }

  onClose() {
    this.closed = true;
    this.clearPoll();
    this.contentEl.empty();
    if (!this.loggedIn) {
      void this.plugin.cancelQrLogin(this.account.id).catch(() => {});
    }
  }
}

function normalizeAccounts(settings) {
  const accounts = Array.isArray(settings.accounts)
    ? settings.accounts
      .filter((account) => account && account.id && account.name)
      .map((account) => ({ id: String(account.id), name: String(account.name) }))
    : [];
  if (!accounts.some((account) => account.id === "default")) {
    accounts.unshift({ id: "default", name: "默认账号" });
  }
  const activeAccountId = accounts.some((account) => account.id === settings.activeAccountId)
    ? settings.activeAccountId
    : accounts[0].id;
  return { accounts, activeAccountId };
}

class CsdnDraftPublisherSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    const t = (k, v) => this.plugin.t(k, v);
    containerEl.empty();

    containerEl.createEl("p", {
      text: t("settingsIntro"),
      cls: "setting-item-description",
    });

    new Setting(containerEl)
      .setName(t("settingLanguageName"))
      .setDesc(t("settingLanguageDesc"))
      .addDropdown((dropdown) => {
        dropdown.addOption("auto", t("langAuto"));
        dropdown.addOption("zh", t("langZh"));
        dropdown.addOption("en", t("langEn"));
        dropdown
          .setValue(this.plugin.settings.language || "auto")
          .onChange(async (value) => {
            this.plugin.settings.language = value;
            await this.plugin.saveSettings();
            this.plugin.applyLanguage();
            this.display();
          });
      });

    const accountState = normalizeAccounts(this.plugin.settings);
    this.plugin.settings.accounts = accountState.accounts;
    this.plugin.settings.activeAccountId = accountState.activeAccountId;

    new Setting(containerEl)
      .setName(t("settingActiveAccountName"))
      .setDesc(t("settingActiveAccountDesc"))
      .addDropdown((dropdown) => {
        for (const account of accountState.accounts) {
          dropdown.addOption(account.id, this.plugin.accountDisplayName(account));
        }
        dropdown
          .setValue(accountState.activeAccountId)
          .onChange(async (value) => {
            this.plugin.settings.activeAccountId = value;
            await this.plugin.saveSettings();
            const account = this.plugin.getAccount(value);
            const name = account ? this.plugin.accountDisplayName(account) : value;
            new Notice(t("switchedAccountNotice", { name }), 5000);
            this.plugin.refreshOpenDraftViews();
            this.display();
          });
      });

    new Setting(containerEl)
      .setName(t("settingAccountMgmtName"))
      .setDesc(t("settingAccountMgmtDesc"))
      .addButton((button) => button
        .setButtonText(t("addAccountBtn"))
        .onClick(async () => {
          const name = await new TextInputModal(this.app, {
            title: t("addAccountModalTitle"),
            placeholder: t("addAccountPlaceholder"),
            submitText: t("add"),
            cancelText: t("cancel"),
          }).openAndWait();
          if (!name) return;
          const account = await this.plugin.addAccount(name);
          await this.plugin.saveSettings();
          this.display();
          new Notice(t("accountAddedNotice", { name: account.name }), 8000);
        }));

    for (const account of accountState.accounts) {
      const isActive = account.id === accountState.activeAccountId;
      const displayName = this.plugin.accountDisplayName(account);
      const row = new Setting(containerEl)
        .setName(`${displayName}${isActive ? t("currentBadge") : ""}`)
        .setDesc(account.id === "default" ? t("accountDescDefault") : t("accountDescIsolated"))
        .addButton((button) => button
          .setCta()
          .setButtonText(t("qrLoginBtn"))
          .onClick(() => void this.plugin.openQrLoginModal(account.id)))
        .addButton((button) => button
          .setButtonText(t("browserLoginBtn"))
          .onClick(async () => {
            button.setDisabled(true);
            try {
              await this.plugin.loginAccount(account.id);
              new Notice(t("openedBrowserLoginNotice", { name: displayName }), 8000);
            } catch (error) {
              new Notice(t("openBrowserLoginError", { error: error.message }), 10000);
            } finally {
              button.setDisabled(false);
            }
          }))
        .addButton((button) => button
          .setButtonText(t("checkBtn"))
          .onClick(async () => {
            button.setDisabled(true);
            const checking = new Notice(t("checkingSessionNotice", { name: displayName }), 0);
            try {
              const result = await this.plugin.sessionAccount(account.id, true);
              const status = result.status === "logged_in" ? t("sessionActiveShort") : result.message;
              new Notice(`${displayName}: ${status}`, 8000);
            } catch (error) {
              new Notice(t("checkAccountError", { error: error.message }), 10000);
            } finally {
              checking.hide();
              button.setDisabled(false);
            }
          }))
        .addButton((button) => button
          .setButtonText(t("renameBtn"))
          .onClick(async () => {
            const nextName = await new TextInputModal(this.app, {
              title: t("renameAccountModalTitle"),
              initialValue: displayName,
              submitText: t("save"),
              cancelText: t("cancel"),
            }).openAndWait();
            if (!nextName || nextName === displayName) return;
            account.name = nextName;
            await this.plugin.saveSettings();
            this.plugin.applyLanguage();
            this.display();
            new Notice(t("accountRenamedNotice", { name: nextName }), 5000);
          }))
        .addButton((button) => button
          .setWarning()
          .setButtonText(t("clearSessionBtn"))
          .onClick(async () => {
            const confirmed = await new ConfirmModal(this.app, {
              title: t("clearSessionModalTitle"),
              message: t("clearSessionModalMsg", { name: displayName }),
              confirmText: t("confirmClear"),
              cancelText: t("cancel"),
            }).openAndWait();
            if (!confirmed) return;
            button.setDisabled(true);
            try {
              await this.plugin.logoutAccount(account.id);
              new Notice(t("sessionClearedNotice", { name: displayName }), 5000);
            } catch (error) {
              new Notice(t("clearSessionError", { error: error.message }), 10000);
            } finally {
              button.setDisabled(false);
            }
          }));

      if (account.id !== "default") {
        row.addButton((button) => button
          .setWarning()
          .setButtonText(t("deleteBtn"))
          .onClick(async () => {
            const confirmed = await new ConfirmModal(this.app, {
              title: t("deleteAccountModalTitle"),
              message: t("deleteAccountModalMsg", { name: displayName }),
              confirmText: t("deleteBtn"),
              cancelText: t("cancel"),
            }).openAndWait();
            if (!confirmed) return;
            button.setDisabled(true);
            try {
              try {
                await this.plugin.logoutAccount(account.id);
              } catch {
                // Bridge may be offline; still allow removing account from settings.
              }
              this.plugin.settings.accounts = this.plugin.settings.accounts.filter((a) => a.id !== account.id);
              if (this.plugin.settings.activeAccountId === account.id) {
                this.plugin.settings.activeAccountId = "default";
              }
              await this.plugin.saveSettings();
              this.plugin.refreshOpenDraftViews();
              this.display();
              new Notice(t("accountDeletedNotice", { name: displayName }), 5000);
            } finally {
              button.setDisabled(false);
            }
          }));
      }
    }

    new Setting(containerEl)
      .setName(t("settingBridgeEnableName"))
      .setDesc(t("settingBridgeEnableDesc"))
      .addToggle((toggle) => toggle
        .setValue(this.plugin.settings.bridgeEnabled)
        .onChange(async (value) => {
          toggle.setDisabled(true);
          this.plugin.settings.bridgeEnabled = value;
          await this.plugin.saveSettings();
          try {
            if (value) {
              const result = await this.plugin.startBridge();
              const prefix = result.external
                ? t("bridgeAlreadyRunningPrefix")
                : t("bridgeStartedPrefix");
              const suffix = result.playwright === false
                ? t("bridgeNoPlaywrightSuffix")
                : "";
              new Notice(`${prefix}${suffix}${t("bridgeSentenceEnd")}`, 8000);
            } else {
              this.plugin.stopManagedBridge();
              new Notice(t("bridgeStoppedNotice"), 5000);
            }
          } catch (error) {
            this.plugin.settings.bridgeEnabled = false;
            await this.plugin.saveSettings();
            toggle.setValue(false);
            new Notice(t("bridgeStartError", { error: error.message }), 10000);
          } finally {
            toggle.setDisabled(false);
          }
        }));

    new Setting(containerEl)
      .setName(t("settingBridgeUrlName"))
      .setDesc(t("settingBridgeUrlDesc"))
      .addText((text) => text
        .setPlaceholder(DEFAULT_SETTINGS.bridgeUrl)
        .setValue(this.plugin.settings.bridgeUrl)
        .onChange(async (value) => {
          this.plugin.settings.bridgeUrl = value.trim().replace(/\/$/, "");
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName(t("settingPythonName"))
      .setDesc(t("settingPythonDesc"))
      .addText((text) => text
        .setPlaceholder(DEFAULT_SETTINGS.pythonCommand)
        .setValue(this.plugin.settings.pythonCommand)
        .onChange(async (value) => {
          this.plugin.settings.pythonCommand = value.trim();
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName(t("settingOpenBrowserName"))
      .setDesc(t("settingOpenBrowserDesc"))
      .addToggle((toggle) => toggle
        .setValue(this.plugin.settings.openBrowser)
        .onChange(async (value) => {
          this.plugin.settings.openBrowser = value;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName(t("settingAutoSaveWaitName"))
      .setDesc(t("settingAutoSaveWaitDesc"))
      .addSlider((slider) => slider
        .setLimits(2, 20, 1)
        .setValue(this.plugin.settings.autoSaveWaitSeconds)
        .setDynamicTooltip()
        .onChange(async (value) => {
          this.plugin.settings.autoSaveWaitSeconds = value;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName(t("settingConvertSyntaxName"))
      .setDesc(t("settingConvertSyntaxDesc"))
      .addToggle((toggle) => toggle
        .setValue(this.plugin.settings.convertObsidianSyntax)
        .onChange(async (value) => {
          this.plugin.settings.convertObsidianSyntax = value;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName(t("settingWriteBackIdName"))
      .setDesc(t("settingWriteBackIdDesc"))
      .addToggle((toggle) => toggle
        .setValue(this.plugin.settings.writeBackArticleId)
        .onChange(async (value) => {
          this.plugin.settings.writeBackArticleId = value;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName(t("settingVerifyKernelName"))
      .setDesc(t("settingVerifyKernelDesc"))
      .addButton((button) => button
        .setButtonText(t("checkServiceBtn"))
        .onClick(async () => {
          button.setDisabled(true);
          try {
            const result = await this.plugin.healthCheck();
            const version = result.bridge_api_version || t("legacyVersion");
            const accountSupport = result.account_profiles ? t("multiAccountEnabled") : t("multiAccountUnsupported");
            const pw = result.playwright ? t("playwrightInstalled") : t("playwrightMissing");
            new Notice(t("healthOkNotice", { version, pw, multi: accountSupport }));
          } catch (error) {
            const hint = this.plugin.settings.bridgeEnabled
              ? t("healthHintEnabled")
              : t("healthHintDisabled");
            new Notice(t("healthFailNotice", { error: error.message, hint }), 10000);
          } finally {
            button.setDisabled(false);
          }
        }))
      .addButton((button) => button
        .setButtonText(t("installKernelBtn"))
        .onClick(async () => {
          button.setDisabled(true);
          const installing = new Notice(t("installingKernelNotice"), 0);
          try {
            await this.plugin.installPlaywrightBrowser();
            new Notice(t("installKernelDoneNotice"), 8000);
          } catch (error) {
            new Notice(t("installKernelError", { error: error.message }), 10000);
          } finally {
            installing.hide();
            button.setDisabled(false);
          }
        }));
  }
}

class CsdnDraftPublisher extends Plugin {
  getLang() {
    return resolveLang(this.settings);
  }

  t(key, vars = {}) {
    return translate(this.getLang(), key, vars);
  }

  accountDisplayName(account) {
    if (!account) return this.t("defaultAccountName");
    if (
      account.id === "default"
      && (account.name === "默认账号" || account.name === "Default account")
    ) {
      return this.t("defaultAccountName");
    }
    return account.name;
  }

  registerLocalizedCommands() {
    const defs = [
      {
        id: "sync-current-note-to-csdn-draft",
        name: this.t("cmdSyncNote"),
        checkCallback: (checking) => {
          const file = this.app.workspace.getActiveFile();
          const enabled = Boolean(file && file.extension === "md");
          if (!checking && enabled) void this.syncCurrentNote();
          return enabled;
        },
      },
      {
        id: "open-csdn-draft-box",
        name: this.t("cmdOpenDraftBox"),
        callback: () => void this.openDraftBox(),
      },
      {
        id: "qr-login-csdn",
        name: this.t("cmdQrLogin"),
        callback: () => void this.openQrLoginModal(this.settings.activeAccountId),
      },
    ];
    for (const def of defs) {
      if (typeof this.removeCommand === "function") {
        try {
          this.removeCommand(def.id);
        } catch {
          // Ignore when registering for the first time.
        }
      }
      this.addCommand(def);
    }
  }

  applyLanguage() {
    this.registerLocalizedCommands();
    if (this.ribbonEl) {
      this.ribbonEl.setAttribute("aria-label", this.t("ribbonTooltip"));
    }
    for (const leaf of this.app.workspace.getLeavesOfType(DRAFT_VIEW_TYPE)) {
      try {
        leaf.updateHeader?.();
      } catch {
        // Ignore if Obsidian version does not expose updateHeader.
      }
      if (leaf.view && typeof leaf.view.render === "function") {
        void leaf.view.render();
      }
    }
  }

  async onload() {
    await this.loadSettings();
    addIcon("csdn-brand", CSDN_C_ICON_SVG);
    this.registerView(DRAFT_VIEW_TYPE, (leaf) => new CsdnDraftBoxView(leaf, this));

    if (this.settings.bridgeEnabled) {
      void this.startBridge().catch((error) => {
        new Notice(this.t("bridgeStartError", { error: error.message }), 10000);
      });
    }

    this.registerLocalizedCommands();

    this.ribbonEl = this.addRibbonIcon("csdn-brand", this.t("ribbonTooltip"), (event) => {
      new Menu()
        .addItem((item) => item
          .setIcon("upload")
          .setTitle(this.t("cmdSyncNote"))
          .onClick(() => void this.syncCurrentNote()))
        .addItem((item) => item
          .setIcon("external-link")
          .setTitle(this.t("cmdOpenInEditor"))
          .onClick(() => void this.openCurrentNoteInCsdnEditor()))
        .addItem((item) => item
          .setIcon("files")
          .setTitle(this.t("cmdOpenDraftBox"))
          .onClick(() => void this.openDraftBox()))
        .addSeparator()
        .addItem((item) => item
          .setIcon("qr-code")
          .setTitle(this.t("cmdQrLogin"))
          .onClick(() => void this.openQrLoginModal(this.settings.activeAccountId)))
        .showAtMouseEvent(event);
    });

    this.addSettingTab(new CsdnDraftPublisherSettingTab(this.app, this));
  }

  onunload() {
    this.stopManagedBridge();
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
    const accountState = normalizeAccounts(this.settings);
    this.settings.accounts = accountState.accounts;
    this.settings.activeAccountId = accountState.activeAccountId;
    await this.saveSettings();
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  getAccount(accountId) {
    return this.settings.accounts.find((account) => account.id === accountId);
  }

  async addAccount(name) {
    const account = {
      id: `account-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      name,
    };
    this.settings.accounts.push(account);
    this.settings.activeAccountId = account.id;
    return account;
  }

  async accountRequest(pathname, accountId, method = "GET") {
    const query = new URLSearchParams({
      account_id: accountId,
      lang: this.getLang(),
    });
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}${pathname}?${query.toString()}`,
      method,
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async listDrafts(accountId, page = 1, keyword = "") {
    const query = new URLSearchParams({
      account_id: accountId,
      page: String(page),
      page_size: "20",
      keyword,
      lang: this.getLang(),
    });
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/drafts?${query.toString()}`,
      method: "GET",
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async getDraft(accountId, articleId) {
    const query = new URLSearchParams({
      account_id: accountId,
      article_id: articleId,
      lang: this.getLang(),
    });
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/draft?${query.toString()}`,
      method: "GET",
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async deleteDraft(accountId, articleId) {
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/drafts/delete`,
      method: "POST",
      contentType: "application/json",
      body: JSON.stringify({ account_id: accountId, article_id: articleId, lang: this.getLang() }),
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async importDraftToVault(item) {
    const account = this.getAccount(this.settings.activeAccountId) || DEFAULT_SETTINGS.accounts[0];
    const result = await this.getDraft(account.id, item.article_id);
    const preferredFolder = this.app.vault.getAbstractFileByPath("CSDN草稿")
      ? "CSDN草稿"
      : (this.getLang() === "en" && !this.app.vault.getAbstractFileByPath("CSDN草稿")
        ? (this.app.vault.getAbstractFileByPath("CSDN Drafts") ? "CSDN Drafts" : "CSDN Drafts")
        : "CSDN草稿");
    if (!this.app.vault.getAbstractFileByPath(preferredFolder)) {
      await this.app.vault.createFolder(preferredFolder);
    }

    const articleId = asString(result.article_id || item.article_id);
    const title = asString(result.title || item.title || this.t("untitledDraft"));
    const markdown = [
      "---",
      "type: csdn-draft",
      "status: draft",
      `created: ${new Date().toISOString()}`,
      `updated: ${new Date().toISOString()}`,
      `csdn_article_id: ${articleId}`,
      `csdn_account_id: ${yamlString(result.account_id || account.id)}`,
      "---",
      "",
      `# ${title}`,
      "",
      asString(result.content).trim(),
      "",
    ].join("\n");

    let file = null;
    for (const candidate of this.app.vault.getMarkdownFiles()) {
      if (!candidate.path.startsWith("CSDN草稿/") && !candidate.path.startsWith("CSDN Drafts/")) continue;
      const candidateRaw = await this.app.vault.read(candidate);
      const candidateFrontmatter = parseFrontmatter(candidateRaw).data;
      if (asString(candidateFrontmatter.csdn_article_id) === articleId) {
        file = candidate;
        break;
      }
    }
    if (!file) {
      file = await this.app.vault.create(
        `${preferredFolder}/${safeDraftFileName(title, articleId, this.t("untitledDraft"))}`,
        markdown
      );
    } else {
      await this.app.vault.modify(file, markdown);
    }

    await this.app.workspace.getLeaf(false).openFile(file);
    new Notice(this.t("importedDraftNotice", { path: file.path }), 8000);
    return file;
  }

  async openCurrentNoteInCsdnEditor() {
    const file = this.app.workspace.getActiveFile();
    if (!file || file.extension !== "md") {
      new Notice(this.t("openMdFirstNotice"), 6000);
      return;
    }

    const notice = new Notice(this.t("openingCsdnEditorNotice"), 0);
    try {
      const raw = await this.app.vault.read(file);
      const parsed = parseFrontmatter(raw);
      const frontmatter = parsed.data;
      const metadata = this.app.metadataCache.getFileCache(file)?.frontmatter || {};
      const title = asString(frontmatter.title || metadata.title || firstHeading(parsed.body) || file.basename);
      const cleanedBody = removeDuplicateTitle(parsed.body, title);
      const body = this.settings.convertObsidianSyntax
        ? preprocessObsidianMarkdown(cleanedBody)
        : cleanedBody;
      const tags = normalizeList(frontmatter.tags || metadata.tags);
      const description = asString(frontmatter.description || frontmatter.summary || metadata.description);
      const cover = asString(frontmatter.cover || frontmatter.image || metadata.cover || metadata.image);
      const draftArticleId = asString(frontmatter.csdn_article_id || frontmatter.csdn_articleId);
      const draftAccountId = asString(frontmatter.csdn_account_id);
      const account = this.getAccount(draftAccountId || this.settings.activeAccountId) || DEFAULT_SETTINGS.accounts[0];

      const response = await requestUrl({
        url: `${this.settings.bridgeUrl}/open-editor`,
        method: "POST",
        contentType: "application/json",
        body: JSON.stringify({
          title,
          content: body,
          tags,
          description,
          cover,
          account_id: account.id,
          article_id: /^\d+$/.test(draftArticleId) ? draftArticleId : "",
          lang: this.getLang(),
        }),
        throw: false,
      });
      const result = JSON.parse(response.text || "{}");
      if (response.status < 200 || response.status >= 300 || !result.ok) {
        throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
      }
      new Notice(this.t("openedInCsdnEditorNotice", { title }), 9000);
    } catch (error) {
      new Notice(this.t("openCsdnEditorError", { error: error.message }), 10000);
    } finally {
      notice.hide();
    }
  }

  async openDraftBox() {
    const existing = this.app.workspace.getLeavesOfType(DRAFT_VIEW_TYPE)[0];
    if (existing) {
      this.app.workspace.revealLeaf(existing);
      return;
    }
    const leaf = this.app.workspace.getRightLeaf(false) || this.app.workspace.getLeaf(true);
    await leaf.setViewState({ type: DRAFT_VIEW_TYPE, active: true });
    this.app.workspace.revealLeaf(leaf);
  }

  refreshOpenDraftViews() {
    for (const leaf of this.app.workspace.getLeavesOfType(DRAFT_VIEW_TYPE)) {
      const view = leaf.view;
      if (view && typeof view.loadDrafts === "function") {
        view.page = 1;
        void view.loadDrafts();
      }
    }
  }

  async loginAccount(accountId) {
    return this.accountRequest("/login", accountId);
  }

  async openQrLoginModal(accountId) {
    const account = this.getAccount(accountId || this.settings.activeAccountId) || DEFAULT_SETTINGS.accounts[0];
    try {
      const health = await this.healthCheck();
      if (!health.qr_login) {
        new Notice(this.t("bridgeLegacyQrNotice"), 10000);
        return;
      }
    } catch {
      if (this.settings.bridgeEnabled) {
        try {
          await this.startBridge();
        } catch (error) {
          new Notice(this.t("bridgeStartError", { error: error.message }), 10000);
          return;
        }
      } else {
        new Notice(this.t("bridgeNotStartedNotice"), 8000);
        return;
      }
    }
    new QrLoginModal(this.app, this, account).open();
  }

  async startQrLogin(accountId, mode = "wechat", forceRelogin = false) {
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/login/qr/start`,
      method: "POST",
      contentType: "application/json",
      body: JSON.stringify({
        account_id: accountId,
        mode,
        force_relogin: forceRelogin,
        lang: this.getLang(),
      }),
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async refreshQrLogin(accountId, mode = "wechat") {
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/login/qr/refresh`,
      method: "POST",
      contentType: "application/json",
      body: JSON.stringify({ account_id: accountId, mode, lang: this.getLang() }),
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async getQrLoginStatus(accountId) {
    const query = new URLSearchParams({ account_id: accountId, lang: this.getLang() });
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/login/qr/status?${query.toString()}`,
      method: "GET",
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async cancelQrLogin(accountId) {
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/login/qr/cancel`,
      method: "POST",
      contentType: "application/json",
      body: JSON.stringify({ account_id: accountId, lang: this.getLang() }),
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async sessionAccount(accountId, verify = false) {
    const query = new URLSearchParams({ account_id: accountId, lang: this.getLang() });
    if (verify) query.set("verify", "1");
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/session?${query.toString()}`,
      method: "GET",
      throw: false,
    });
    const result = JSON.parse(response.text || "{}");
    if (response.status < 200 || response.status >= 300 || !result.ok) {
      throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
    }
    return result;
  }

  async logoutAccount(accountId) {
    return this.accountRequest("/logout", accountId, "POST");
  }

  getBridgeScriptPath() {
    // this.manifest.dir is vault-relative in Obsidian (e.g. ".obsidian/plugins/csdn-draft-publisher").
    // Resolve it against the vault's basePath so Node's fs/spawn always receive an absolute path.
    const pluginDir = this.manifest.dir
      || path.join(this.app.vault.configDir || ".obsidian", "plugins", this.manifest.id);
    const basePath = this.app.vault.adapter?.basePath || "";
    const absDir = path.isAbsolute(pluginDir) || !basePath
      ? pluginDir
      : path.join(basePath, pluginDir);
    return path.join(absDir, "csdn_bridge.py");
  }

  ensureBridgeScript(scriptPath) {
    const expected = Buffer.from(EMBEDDED_BRIDGE_SCRIPT_B64, "base64");
    try {
      if (fs.existsSync(scriptPath)) {
        const existing = fs.readFileSync(scriptPath);
        if (existing.equals(expected)) return true;
      }
      fs.mkdirSync(path.dirname(scriptPath), { recursive: true });
      fs.writeFileSync(scriptPath, expected);
      return true;
    } catch (error) {
      new Notice(this.t("extractBridgeError", { error: error.message }), 10000);
      return false;
    }
  }

  getBridgePort() {
    try {
      return String(new URL(this.settings.bridgeUrl).port || "8765");
    } catch {
      return "8765";
    }
  }

  async isBridgeAvailable() {
    try {
      await this.healthCheck();
      return true;
    } catch {
      return false;
    }
  }

  async waitForBridge(timeoutMs = 10000) {
    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      try {
        return await this.healthCheck();
      } catch {
        // Keep polling while the Python process is starting.
      }
      await new Promise((resolve) => window.setTimeout(resolve, 300));
    }
    return null;
  }

  getPythonCommands() {
    const candidates = [
      this.settings.pythonCommand,
      "python",
      "py",
    ].filter(Boolean);
    return [...new Set(candidates)];
  }

  installPlaywrightBrowser() {
    const command = this.getPythonCommands()[0] || "python";
    return new Promise((resolve, reject) => {
      let stderr = "";
      const child = spawn(command, ["-m", "playwright", "install", "chromium"], {
        windowsHide: true,
      });
      child.stderr?.on("data", (chunk) => {
        stderr += String(chunk);
      });
      child.once("error", (error) => reject(error));
      child.once("exit", (code) => {
        if (code === 0) {
          resolve();
        } else {
          reject(new Error(stderr.trim() || this.t("pwInstallExitError", { code })));
        }
      });
    });
  }

  launchBridgeProcess(command, scriptPath) {
    return new Promise((resolve, reject) => {
      const child = spawn(command, [
        scriptPath,
        "--host",
        "127.0.0.1",
        "--port",
        this.getBridgePort(),
      ], {
        cwd: path.dirname(scriptPath),
        windowsHide: true,
        stdio: "ignore",
      });

      const handleError = (error) => {
        child.removeListener("spawn", handleSpawn);
        reject(error);
      };
      const handleSpawn = () => {
        child.removeListener("error", handleError);
        resolve(child);
      };
      child.once("error", handleError);
      child.once("spawn", handleSpawn);
    });
  }

  async startBridge() {
    // Always keep the extracted bridge script up to date before checking or spawning.
    const scriptPath = this.getBridgeScriptPath();
    this.ensureBridgeScript(scriptPath);

    let existingHealth = null;
    try {
      existingHealth = await this.healthCheck();
    } catch {
      // The bridge is not responding; start it below if the toggle requested it.
    }
    if (existingHealth) {
      if (existingHealth.bridge_api_version !== BRIDGE_API_VERSION || existingHealth.account_profiles !== true) {
        throw new Error(this.t("bridgeLegacyRunningError"));
      }
      return { external: true, playwright: existingHealth.playwright };
    }

    if (this.bridgeProcess && !this.bridgeProcess.killed) {
      const health = await this.waitForBridge();
      if (health) {
        return { external: false, playwright: health.playwright };
      }
      throw new Error(this.t("bridgeNoResponseError"));
    }

    if (!fs.existsSync(scriptPath)) {
      throw new Error(this.t("bridgeScriptMissingError", { path: scriptPath }));
    }

    let child = null;
    let launchError = null;
    let launchedCommand = "";
    for (const command of this.getPythonCommands()) {
      try {
        child = await this.launchBridgeProcess(command, scriptPath);
        launchedCommand = command;
        break;
      } catch (error) {
        launchError = error;
      }
    }
    if (!child) {
      throw new Error(this.t("pythonLaunchError", {
        error: launchError?.message || this.t("noPythonFound"),
      }));
    }

    this.bridgeProcess = child;
    this.bridgeProcessStartedByPlugin = true;
    child.once("error", (error) => {
      if (this.bridgeProcess === child) {
        this.bridgeProcess = null;
        this.bridgeProcessStartedByPlugin = false;
      }
      new Notice(this.t("bridgeProcessError", { error: error.message }), 10000);
    });
    child.once("exit", () => {
      if (this.bridgeProcess === child) {
        this.bridgeProcess = null;
        this.bridgeProcessStartedByPlugin = false;
      }
    });

    const health = await this.waitForBridge();
    if (health?.playwright) {
      return { external: false, playwright: health.playwright };
    }

    this.stopManagedBridge();
    if (health && health.playwright === false) {
      throw new Error(this.t("bridgeStartedNoPwError", { cmd: launchedCommand }));
    }
    throw new Error(this.t("bridgeTimeoutError"));
  }

  stopManagedBridge() {
    if (!this.bridgeProcessStartedByPlugin || !this.bridgeProcess) return;
    const child = this.bridgeProcess;
    this.bridgeProcess = null;
    this.bridgeProcessStartedByPlugin = false;
    try {
      child.kill();
    } catch (error) {
      // The process may have exited between the state check and kill().
    }
  }

  async healthCheck() {
    const response = await requestUrl({
      url: `${this.settings.bridgeUrl}/health`,
      method: "GET",
      throw: false,
    });
    if (response.status < 200 || response.status >= 300) {
      throw new Error(`HTTP ${response.status}`);
    }
    return JSON.parse(response.text);
  }

  async syncCurrentNote() {
    const file = this.app.workspace.getActiveFile();
    if (!file || file.extension !== "md") {
      new Notice(this.t("openMdFirstNotice"));
      return;
    }

    const notice = new Notice(this.t("preparingDraftNotice"), 0);
    try {
      const raw = await this.app.vault.read(file);
      const parsed = parseFrontmatter(raw);
      const frontmatter = parsed.data;
      const metadata = this.app.metadataCache.getFileCache(file)?.frontmatter || {};
      const title = asString(frontmatter.title || metadata.title || firstHeading(parsed.body) || file.basename);
      const cleanedBody = removeDuplicateTitle(parsed.body, title);
      const body = this.settings.convertObsidianSyntax
        ? preprocessObsidianMarkdown(cleanedBody)
        : cleanedBody;
      const tags = normalizeList(frontmatter.tags || metadata.tags);
      const description = asString(frontmatter.description || frontmatter.summary || metadata.description);
      const cover = asString(frontmatter.cover || frontmatter.image || metadata.cover || metadata.image);
      const draftArticleId = asString(frontmatter.csdn_article_id || frontmatter.csdn_articleId);
      const draftAccountId = asString(frontmatter.csdn_account_id);
      const localImages = findLocalImages(body);
      const basePath = this.app.vault.adapter.basePath || "";
      const sourcePath = basePath ? `${basePath}/${file.path}` : file.path;
      const account = this.getAccount(draftAccountId || this.settings.activeAccountId) || DEFAULT_SETTINGS.accounts[0];
      const accountName = this.accountDisplayName(account);

      const response = await requestUrl({
        url: `${this.settings.bridgeUrl}/sync`,
        method: "POST",
        contentType: "application/json",
        body: JSON.stringify({
          title,
          content: body,
          tags,
          description,
          cover,
          source_path: sourcePath,
          source_file: file.path,
          open_browser: this.settings.openBrowser,
          auto_save_wait_seconds: this.settings.autoSaveWaitSeconds,
          account_id: account.id,
          article_id: /^\d+$/.test(draftArticleId) ? draftArticleId : "",
          lang: this.getLang(),
        }),
        throw: false,
      });

      const result = JSON.parse(response.text || "{}");
      if (response.status < 200 || response.status >= 300 || !result.ok) {
        throw new Error(result.error || this.t("bridgeHttpError", { status: response.status }));
      }

      const returnedArticleId = asString(result.article_id);
      let wroteBackId = false;
      if (
        this.settings.writeBackArticleId
        && /^\d+$/.test(returnedArticleId)
        && returnedArticleId !== draftArticleId
      ) {
        try {
          await this.app.fileManager.processFrontMatter(file, (fm) => {
            fm.csdn_article_id = returnedArticleId;
            fm.csdn_account_id = account.id;
          });
          wroteBackId = true;
        } catch {
          // Non-fatal: draft is already saved on CSDN.
        }
      }

      const warning = localImages.length
        ? this.t("localImgWarningSuffix", { count: localImages.length })
        : "";
      const idNote = wroteBackId ? this.t("wroteBackIdNote", { id: returnedArticleId }) : "";
      if (result.saved) {
        const action = result.updated_existing ? this.t("actionUpdateDraft") : this.t("actionCreateDraft");
        new Notice(this.t("syncSuccessNotice", {
          account: accountName,
          action,
          title,
          idNote,
          warning,
        }), 8000);
      } else {
        new Notice(this.t("syncUnconfirmedNotice", {
          account: accountName,
          idNote,
          warning,
        }), 10000);
      }
    } catch (error) {
      new Notice(this.t("syncErrorNotice", { error: error.message }), 10000);
    } finally {
      notice.hide();
    }
  }
}

class CsdnDraftBoxView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.page = 1;
    this.keyword = "";
    this.items = [];
    this.total = null;
    this.loading = false;
    this.lastError = "";
  }

  getViewType() {
    return DRAFT_VIEW_TYPE;
  }

  getDisplayText() {
    return this.plugin.t("draftBoxTabTitle");
  }

  getIcon() {
    return DRAFT_VIEW_ICON;
  }

  async onOpen() {
    await this.render();
    await this.loadDrafts();
  }

  async onClose() {
    this.contentEl.empty();
  }

  activeAccount() {
    return this.plugin.getAccount(this.plugin.settings.activeAccountId)
      || DEFAULT_SETTINGS.accounts[0];
  }

  async render() {
    const { contentEl } = this;
    const t = (k, v) => this.plugin.t(k, v);
    contentEl.empty();
    contentEl.addClass("csdn-draft-box-view");
    const account = this.activeAccount();
    const accountName = this.plugin.accountDisplayName(account);
    const shell = contentEl.createDiv({ cls: "csdn-draft-box-shell" });

    const hero = shell.createDiv({ cls: "csdn-draft-box-hero" });
    const heroCopy = hero.createDiv();
    heroCopy.createDiv({ text: "CSDN CONTENT", cls: "csdn-draft-box-eyebrow" });
    heroCopy.createEl("h2", { text: t("draftBoxHeading") });
    heroCopy.createEl("p", {
      text: t("draftBoxSubtitle"),
      cls: "csdn-draft-box-subtitle",
    });
    hero.createDiv({ text: t("draftBoxAccountBadge", { name: accountName }), cls: "csdn-draft-box-account" });

    const summary = shell.createDiv({ cls: "csdn-draft-box-summary" });
    const stats = [
      [t("statTotalLabel"), this.total === null ? (this.loading ? "—" : String(this.items.length)) : String(this.total)],
      [t("statPageLabel"), this.loading ? "—" : t("statPageValue", { count: this.items.length })],
      [t("statModeLabel"), t("statModeValue")],
    ];
    for (const [label, value] of stats) {
      const stat = summary.createDiv({ cls: "csdn-draft-box-stat" });
      stat.createDiv({ text: label, cls: "csdn-draft-box-stat-label" });
      stat.createDiv({ text: value, cls: "csdn-draft-box-stat-value" });
    }

    const toolbar = shell.createDiv({ cls: "csdn-draft-box-toolbar" });
    const search = toolbar.createEl("input", {
      type: "search",
      placeholder: t("searchPlaceholder"),
      value: this.keyword,
      cls: "csdn-draft-box-search",
    });
    search.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        this.keyword = search.value.trim();
        this.page = 1;
        void this.loadDrafts();
      }
    });
    const searchButton = toolbar.createEl("button", { text: t("searchBtn") });
    searchButton.addEventListener("click", () => {
      this.keyword = search.value.trim();
      this.page = 1;
      void this.loadDrafts();
    });
    const refreshButton = toolbar.createEl("button", { text: t("refreshBtn") });
    refreshButton.addEventListener("click", () => void this.loadDrafts());
    const qrLoginButton = toolbar.createEl("button", { text: t("qrLoginBtn") });
    qrLoginButton.addEventListener("click", () => void this.plugin.openQrLoginModal(account.id));

    const list = shell.createDiv({ cls: "csdn-draft-box-list" });
    if (this.loading) {
      for (let index = 0; index < 6; index += 1) {
        list.createDiv({ cls: "csdn-draft-box-skeleton" });
      }
    } else if (this.lastError) {
      const stateBox = list.createDiv({ cls: "csdn-draft-box-state" });
      stateBox.createDiv({ text: this.lastError });
    } else if (!this.items.length) {
      list.createDiv({ text: t("emptyDraftsState"), cls: "csdn-draft-box-state" });
    } else {
      for (const item of this.items) {
        const card = list.createDiv({ cls: "csdn-draft-box-card" });
        const top = card.createDiv({ cls: "csdn-draft-box-card-top" });
        top.createSpan({ text: "CSDN DRAFT", cls: "csdn-draft-box-badge" });
        top.createSpan({ text: item.updated_at || t("recentlyUpdated") });
        card.createEl("h3", { text: item.title || t("untitledBracket") });
        card.createDiv({ text: t("articleIdMeta", { id: item.article_id }), cls: "csdn-draft-box-card-meta" });
        const actions = card.createDiv({ cls: "csdn-draft-box-actions" });
        const edit = actions.createEl("button", { text: t("importBtn") });
        edit.addEventListener("click", () => void this.editDraft(item, edit));
        const remove = actions.createEl("button", { text: t("deleteBtn") });
        remove.addClass("mod-warning");
        remove.addEventListener("click", () => void this.removeDraft(item));
      }
    }

    const pager = shell.createDiv({ cls: "csdn-draft-box-pager" });
    const previous = pager.createEl("button", { text: t("prevPageBtn") });
    previous.disabled = this.loading || this.page <= 1;
    previous.addEventListener("click", () => {
      if (this.page > 1) {
        this.page -= 1;
        void this.loadDrafts();
      }
    });
    pager.createSpan({ text: t("pageIndicator", { page: this.page }) });
    const next = pager.createEl("button", { text: t("nextPageBtn") });
    next.disabled = this.loading || this.items.length < 20;
    next.addEventListener("click", () => {
      if (this.items.length >= 20) {
        this.page += 1;
        void this.loadDrafts();
      }
    });
  }

  async editDraft(item, button) {
    button.textContent = this.plugin.t("importingBtn");
    button.disabled = true;
    try {
      await this.plugin.importDraftToVault(item);
    } catch (error) {
      new Notice(this.plugin.t("importDraftError", { error: error.message }), 10000);
    } finally {
      button.textContent = this.plugin.t("importBtn");
      button.disabled = false;
    }
  }

  async loadDrafts() {
    if (this.loading) return;
    this.loading = true;
    this.lastError = "";
    await this.render();
    try {
      const account = this.activeAccount();
      const result = await this.plugin.listDrafts(account.id, this.page, this.keyword);
      this.items = Array.isArray(result.items) ? result.items : [];
      this.total = Number.isFinite(Number(result.total)) ? Number(result.total) : null;
      this.lastError = "";
    } catch (error) {
      this.items = [];
      this.total = null;
      this.lastError = error.message || this.plugin.t("loadDraftsErrorFallback");
      new Notice(this.plugin.t("loadDraftsErrorNotice", { error: error.message }), 10000);
    } finally {
      this.loading = false;
      await this.render();
    }
  }

  async removeDraft(item) {
    const t = (k, v) => this.plugin.t(k, v);
    const account = this.activeAccount();
    const title = item.title || t("untitledBracket");
    const confirmed = await new ConfirmModal(this.app, {
      title: t("deleteDraftModalTitle"),
      message: t("deleteDraftModalMsg", { title }),
      confirmText: t("confirmDelete"),
      cancelText: t("cancel"),
    }).openAndWait();
    if (!confirmed) return;
    try {
      await this.plugin.deleteDraft(account.id, item.article_id);
      new Notice(t("deletedDraftNotice", { title }), 6000);
      await this.loadDrafts();
    } catch (error) {
      new Notice(t("deleteDraftErrorNotice", { error: error.message }), 10000);
    }
  }
}

module.exports = CsdnDraftPublisher;
